window.HOLUS_JOURNEYS={"ap-1":{"id":"ap-1","after":6,"title":"A tour of the body cavities","token":"#71836d","hideCore":true,"stops":[{"short":"Cranial","place":"Cranial cavity","view":"head","organs":["brain"],"label":[298,52,"start"],"title":"The cranial cavity holds the brain.","body":"The dorsal cavity holds the organs of the nervous system that coordinate the body. Its first part, the cranial cavity, holds the brain.","lensCaption":"The brain, protected inside the skull","scene":"none","path":[[250,60]],"lens":[{"x":50,"y":50,"w":150,"h":110,"r":"46% 54% 50% 50%","bg":"#e3b9b0","border":"none","o":1},{"x":50,"y":50,"w":6,"h":96,"r":"3px","bg":"#cf9a8e","border":"none","o":1},{"x":32,"y":40,"w":40,"h":6,"r":"3px","bg":"#cf9a8e","border":"none","o":1},{"x":68,"y":40,"w":40,"h":6,"r":"3px","bg":"#cf9a8e","border":"none","o":1},{"x":34,"y":62,"w":36,"h":6,"r":"3px","bg":"#cf9a8e","border":"none","o":1},{"x":66,"y":62,"w":36,"h":6,"r":"3px","bg":"#cf9a8e","border":"none","o":1}]},{"short":"Spinal","place":"Spinal cavity","view":"torso","organs":["spine"],"label":[262,300,"start"],"title":"The spinal cavity holds the spinal cord.","body":"The second part of the dorsal cavity runs down the back inside the vertebrae and holds the spinal cord.","lensCaption":"The spinal cord inside a vertebra","scene":"none","path":[[250,90],[250,190],[250,300]],"lens":[{"x":50,"y":50,"w":150,"h":150,"r":"50%","bg":"#f4efe1","border":"10px solid #cfc4a6","o":1},{"x":50,"y":50,"w":62,"h":62,"r":"50%","bg":"#d9bfd2","border":"none","o":1},{"x":50,"y":50,"w":26,"h":26,"r":"40%","bg":"#b07aa0","border":"none","o":1}]},{"short":"Thoracic","place":"Thoracic cavity","view":"chest","organs":["heart","lungs","thymus","trachea"],"label":[330,190,"start"],"title":"The thoracic cavity sits inside the rib cage.","body":"It’s the first part of the ventral cavity. The heart sits in the pericardial cavity and each lung in a pleural cavity. Between them, the mediastinum holds the heart, thymus, trachea, esophagus and vessels.","analogy":"Like a cabinet with a separate drawer for each lung and one in the middle for the heart.","lensCaption":"Heart between the two lungs","scene":"none","path":[[250,240],[262,230]],"lens":[{"x":24,"y":50,"w":70,"h":110,"r":"46% 54% 50% 50%","bg":"#e7a9a0","border":"none","o":1},{"x":76,"y":50,"w":70,"h":110,"r":"46% 54% 50% 50%","bg":"#e7a9a0","border":"none","o":1},{"x":50,"y":54,"w":56,"h":50,"r":"50% 50% 46% 46%","bg":"#c86d56","border":"none","o":1}]},{"short":"Diaphragm","place":"Diaphragm","view":"torso","organs":["diaphragm"],"label":[350,280,"start"],"title":"The diaphragm divides the ventral cavity.","body":"This dome-shaped muscle separates the thoracic cavity above from the abdominopelvic cavity below.","lensCaption":"A sheet of muscle between the two cavities","scene":"muscle","path":[[250,262]],"lens":[]},{"short":"Abdominal","place":"Abdominopelvic cavity","view":"torso","organs":["stomach","liver","gallbladder","intestine","colon","spleen","pancreas","kidneys"],"label":[352,420,"start"],"title":"The abdominopelvic cavity holds the digestive organs.","body":"It holds the kidneys, stomach, liver and gallbladder, small and large intestines, spleen and pancreas. The parietal peritoneum lines its wall; the visceral peritoneum covers the organs.","analogy":"Parietal is the wallpaper; visceral is the gift wrap on each organ.","lensCaption":"Organs wrapped in visceral peritoneum","scene":"none","path":[[252,300],[262,350],[252,420]],"lens":[{"x":30,"y":36,"w":64,"h":52,"r":"46% 54% 50% 50%","bg":"#9a5d50","border":"none","o":1},{"x":68,"y":34,"w":58,"h":50,"r":"46% 54% 50% 50%","bg":"#e09c88","border":"none","o":1},{"x":46,"y":70,"w":80,"h":50,"r":"46% 54% 50% 50%","bg":"#e3a68c","border":"none","o":1},{"x":50,"y":50,"w":200,"h":200,"r":"50%","bg":"transparent","border":"4px dashed #71836d","o":1}]},{"short":"Pelvic organs","place":"Pelvic part","view":"pelvis","organs":["uterus","ovaries"],"label":[300,486,"start"],"title":"In women, it also holds the ovaries and uterus.","body":"The lower, pelvic part of the abdominopelvic cavity holds the reproductive organs in women.","lensCaption":"Uterus with an ovary on each side","scene":"none","path":[[250,470],[250,504]],"lens":[{"x":50,"y":50,"w":74,"h":90,"r":"46% 46% 40% 40%","bg":"#d98aa8","border":"none","o":1},{"x":16,"y":52,"w":30,"h":20,"r":"50%","bg":"#d98aa8","border":"none","o":1},{"x":84,"y":52,"w":30,"h":20,"r":"50%","bg":"#d98aa8","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1: The Human Body"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 1: An Introduction to the Human Body","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified map. Organs are drawn to show which cavity they sit in, not their exact size or position, and the membranes lining each cavity aren’t drawn."},"ap-6":{"id":"ap-6","after":1,"title":"What your skin does, layer by layer","token":"#e0b46a","hideCore":true,"stops":[{"short":"Covering","place":"Skin","view":"body","organs":["skin"],"label":[132,262,"start"],"title":"The skin is the body’s covering.","body":"An adult’s skin covers over 3,000 square inches and weighs about 6 pounds. With the hair, nails and glands, it makes up the integumentary system.","lensCaption":"Skin over the arm","scene":"skin","path":[[114,262]],"lens":[]},{"short":"Epidermis","place":"Epidermis","view":"arm","organs":["skin"],"label":[128,300,"start"],"title":"The epidermis renews itself from the bottom up.","body":"New cells form in the stratum germinativum and move up, filling with keratin. By the stratum corneum they’re dead, flat and constantly shed. The epidermis has no blood vessels.","analogy":"Like a conveyor belt that pushes new tiles up to replace the worn ones on top.","lensCaption":"Cells moving up through the layers","scene":"skin","path":[[110,282],[106,300]],"lens":[{"x":30,"y":12,"w":26,"h":18.2,"r":"40%","bg":"#e8c6ad","border":"2px solid rgba(255,255,255,.7)","o":1},{"x":62,"y":12,"w":26,"h":18.2,"r":"40%","bg":"#e8c6ad","border":"2px solid rgba(255,255,255,.7)","o":1},{"x":22,"y":40,"w":26,"h":18.2,"r":"40%","bg":"#f2d2bc","border":"2px solid rgba(255,255,255,.7)","o":1},{"x":50,"y":40,"w":26,"h":18.2,"r":"40%","bg":"#f2d2bc","border":"2px solid rgba(255,255,255,.7)","o":1},{"x":78,"y":40,"w":26,"h":18.2,"r":"40%","bg":"#f2d2bc","border":"2px solid rgba(255,255,255,.7)","o":1},{"x":36,"y":62,"w":24,"h":16.799999999999997,"r":"40%","bg":"#f7dcc8","border":"2px solid rgba(255,255,255,.7)","o":1},{"x":64,"y":62,"w":24,"h":16.799999999999997,"r":"40%","bg":"#f7dcc8","border":"2px solid rgba(255,255,255,.7)","o":1},{"x":26,"y":84,"w":22,"h":22,"r":"50%","bg":"#e3a07e","border":"none","o":1},{"x":52,"y":84,"w":22,"h":22,"r":"50%","bg":"#e3a07e","border":"none","o":1},{"x":78,"y":84,"w":22,"h":22,"r":"50%","bg":"#8a5a3c","border":"none","o":1}]},{"short":"Melanin","place":"Skin in the sun","view":"arm","organs":["skin"],"label":[118,176,"start"],"title":"Melanin shields against UV rays.","body":"Melanocytes in the stratum germinativum make melanin, the pigment that colours skin. Sunlight stimulates them, which is a suntan. Everyone has about the same number; genes control how much melanin they make.","lensCaption":"Melanin granules around the cells","scene":"skin","path":[[100,240]],"lens":[{"x":20,"y":14,"w":10,"h":40,"r":"4px","bg":"#f0c75a","border":"none","o":0.8},{"x":50,"y":10,"w":10,"h":40,"r":"4px","bg":"#f0c75a","border":"none","o":0.8},{"x":80,"y":14,"w":10,"h":40,"r":"4px","bg":"#f0c75a","border":"none","o":0.8},{"x":30,"y":56,"w":12,"h":12,"r":"50%","bg":"#7a4a2e","border":"none","o":1},{"x":44,"y":62,"w":10,"h":10,"r":"50%","bg":"#7a4a2e","border":"none","o":1},{"x":60,"y":58,"w":12,"h":12,"r":"50%","bg":"#7a4a2e","border":"none","o":1},{"x":72,"y":66,"w":10,"h":10,"r":"50%","bg":"#7a4a2e","border":"none","o":1},{"x":50,"y":84,"w":40,"h":28,"r":"40%","bg":"#8a5a3c","border":"none","o":1}]},{"short":"Dermis","place":"Dermis","view":"arm","organs":["skin","vessels","nerves"],"label":[140,360,"start"],"title":"The dermis holds the working parts.","body":"Below the epidermis, the dermis is dense connective tissue with collagen and elastin. It holds blood vessels, nerves, sweat glands, hair follicles and sebaceous glands. The hypodermis below it stores fat.","lensCaption":"Vessels, a nerve and a sweat gland","scene":"skin","path":[[104,330],[110,360]],"lens":[{"x":30,"y":52,"w":70,"h":8,"r":"4px","bg":"#c86d56","border":"none","o":1},{"x":64,"y":60,"w":70,"h":8,"r":"4px","bg":"#6f91a2","border":"none","o":1},{"x":46,"y":74,"w":60,"h":5,"r":"3px","bg":"#b07aa0","border":"none","o":1},{"x":78,"y":40,"w":24,"h":24,"r":"50%","bg":"#fff","border":"5px solid #9fc0cf","o":1},{"x":78,"y":24,"w":6,"h":20,"r":"3px","bg":"#9fc0cf","border":"none","o":1},{"x":20,"y":30,"w":6,"h":50,"r":"3px","bg":"#5b4636","border":"none","o":1}]},{"short":"Cooling","place":"Sweat glands","view":"arm","organs":["skin","vessels"],"label":[124,410,"start"],"title":"Sweat and blood flow control heat.","body":"Normal temperature is about 37°C. In heat, dermal vessels dilate and eccrine sweat glands release sweat that evaporates. In cold, the vessels narrow to hold heat in.","analogy":"Like opening the windows on a hot day.","lensCaption":"Sweat droplets rising to the surface","scene":"skin","path":[[98,400]],"lens":[{"x":26,"y":10,"w":16,"h":20,"r":"50% 50% 50% 50% / 60% 60% 40% 40%","bg":"#9fc0cf","border":"none","o":1},{"x":54,"y":6,"w":14,"h":18,"r":"50% 50% 50% 50% / 60% 60% 40% 40%","bg":"#9fc0cf","border":"none","o":1},{"x":78,"y":12,"w":16,"h":20,"r":"50% 50% 50% 50% / 60% 60% 40% 40%","bg":"#9fc0cf","border":"none","o":1},{"x":40,"y":34,"w":10,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":66,"y":36,"w":10,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":50,"y":68,"w":120,"h":10,"r":"5px","bg":"#c86d56","border":"none","o":1}]},{"short":"Sensation","place":"Nerves to the brain","view":"body","organs":["skin","nerves","spine","brain"],"label":[276,62,"start"],"title":"Receptors report touch and temperature.","body":"Receptors in the skin for temperature and pressure send signals along nerves to the spinal cord and brain.","lensCaption":"A nerve carrying the signal","scene":"nerve","path":[[104,440],[146,296],[250,222],[250,84],[250,62]],"lens":[{"x":14,"y":50,"w":18,"h":18,"r":"50%","bg":"#fff","border":"4px solid #b07aa0","o":1},{"x":40,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":64,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":0.6},{"x":88,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":0.3}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6: The Integumentary System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 5: The Integumentary System","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified picture. The lens shows layers in cartoon form, and the nerve route to the brain is drawn as one line rather than the real chain of neurons."},"ap-7":{"id":"ap-7","after":0,"title":"Inside the skeleton: support, storage and blood cells","token":"#cfc4a6","hideCore":true,"stops":[{"short":"Framework","place":"Skeleton","view":"body","organs":["skeleton","bones"],"label":[312,180,"start"],"title":"206 bones hold you up.","body":"The adult skeleton has 206 named bones. It supports the body, protects organs, moves with the muscles, makes blood cells and stores minerals.","lensCaption":"Living bone tissue","scene":"osteon","path":[[250,180]],"lens":[]},{"short":"Calcium","place":"Blood to bone","view":"legs","organs":["vessels","bones"],"label":[226,640,"start"],"title":"Calcium is stored in the bone matrix.","body":"Bones are living tissue. Their hardness comes from mineral salts like calcium phosphate, and they release minerals back to the blood when the body needs them.","analogy":"Like a savings account for calcium.","lensCaption":"Calcium moving from blood into bone","scene":"blood","path":[[256,470],[230,560],[210,640]],"lens":[{"x":16,"y":40,"w":12,"h":12,"r":"50%","bg":"#e8dcb8","border":"2px solid #cfc4a6","o":1},{"x":30,"y":56,"w":12,"h":12,"r":"50%","bg":"#e8dcb8","border":"2px solid #cfc4a6","o":1},{"x":46,"y":42,"w":12,"h":12,"r":"50%","bg":"#e8dcb8","border":"2px solid #cfc4a6","o":1},{"x":60,"y":58,"w":12,"h":12,"r":"50%","bg":"#e8dcb8","border":"2px solid #cfc4a6","o":1},{"x":76,"y":44,"w":12,"h":12,"r":"50%","bg":"#e8dcb8","border":"2px solid #cfc4a6","o":1},{"x":88,"y":60,"w":12,"h":12,"r":"50%","bg":"#e8dcb8","border":"2px solid #cfc4a6","o":1},{"x":24,"y":74,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":66,"y":30,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1}]},{"short":"Bone cells","place":"Compact bone","view":"legs","organs":["bones"],"label":[226,690,"start"],"title":"Osteoblasts build; osteoclasts remove.","body":"Osteoblasts lay down bone and become osteocytes once surrounded by matrix. Osteoclasts reabsorb bone during remodelling. In compact bone the unit is the osteon, rings of lamellae around a central canal.","lensCaption":"An osteon: rings around a central canal","scene":"osteon","path":[[209,690]],"lens":[{"x":50,"y":50,"w":30,"h":30,"r":"50%","bg":"#c86d56","border":"4px solid #fff","o":1},{"x":50,"y":20,"w":12,"h":8,"r":"50%","bg":"#8a7a54","border":"none","o":1},{"x":76,"y":40,"w":12,"h":8,"r":"50%","bg":"#8a7a54","border":"none","o":1},{"x":70,"y":74,"w":12,"h":8,"r":"50%","bg":"#8a7a54","border":"none","o":1},{"x":28,"y":74,"w":12,"h":8,"r":"50%","bg":"#8a7a54","border":"none","o":1},{"x":22,"y":38,"w":12,"h":8,"r":"50%","bg":"#8a7a54","border":"none","o":1}]},{"short":"Marrow","place":"Red marrow","view":"torso","organs":["marrow","skeleton"],"label":[300,236,"start"],"title":"Red marrow makes the blood cells.","body":"Spongy bone is a mesh of trabeculae with marrow in the spaces. In adults, red marrow in the ribs, vertebrae, sternum and pelvis makes red and white blood cells and platelets (hematopoiesis).","lensCaption":"New blood cells inside spongy bone","scene":"osteon","path":[[220,560],[250,470],[250,300],[250,236]],"lens":[{"x":24,"y":28,"w":28,"h":17.36,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":60,"y":22,"w":28,"h":17.36,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":78,"y":50,"w":28,"h":17.36,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":36,"y":58,"w":28,"h":17.36,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":58,"y":62,"w":26,"h":26,"r":"50%","bg":"#f4f0f8","border":"3px solid #b07aa0","o":1},{"x":22,"y":80,"w":8,"h":8,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":70,"y":82,"w":8,"h":8,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":46,"y":86,"w":8,"h":8,"r":"50%","bg":"#b07aa0","border":"none","o":1}]},{"short":"Protection","place":"Skull and ribs","view":"torso","organs":["skeleton","heart","lungs"],"label":[340,210,"start"],"title":"Bones protect the vital organs.","body":"The cranium protects the brain, and the rib cage (sternum, ribs and thoracic vertebrae) protects the heart and lungs.","lensCaption":"Ribs around the lungs","scene":"none","path":[[262,228]],"lens":[{"x":50,"y":20,"w":180,"h":10,"r":"5px","bg":"#e8dcb8","border":"none","o":1},{"x":50,"y":40,"w":190,"h":10,"r":"5px","bg":"#e8dcb8","border":"none","o":1},{"x":50,"y":60,"w":190,"h":10,"r":"5px","bg":"#e8dcb8","border":"none","o":1},{"x":50,"y":80,"w":180,"h":10,"r":"5px","bg":"#e8dcb8","border":"none","o":1},{"x":50,"y":50,"w":60,"h":52,"r":"50% 50% 46% 46%","bg":"#c86d56","border":"none","o":1}]},{"short":"Movement","place":"Bones and muscles","view":"arm","organs":["skeleton","tissues"],"label":[150,330,"start"],"title":"Muscles pull on bones as levers.","body":"Muscles attach to bones by tendons. When they contract, bones act as levers and the body moves.","lensCaption":"A muscle pulling on bone","scene":"muscle","path":[[230,240],[146,280],[132,330]],"lens":[{"x":50,"y":34,"w":180,"h":26,"r":"14px","bg":"#e8dcb8","border":"3px solid #cfc4a6","o":1},{"x":50,"y":70,"w":150,"h":40,"r":"40px","bg":"#8fa48a","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7: The Skeletal System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 6: Bone Tissue and the Skeletal System","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified skeleton. Only some bones are drawn, and the lens views are cartoons of tissue, not to scale."},"ap-9":{"id":"ap-9","after":5,"title":"From a thought to a muscle contraction","token":"#b07aa0","hideCore":true,"stops":[{"short":"Brain","place":"Brain","view":"head","organs":["brain"],"label":[296,52,"start"],"title":"You decide to lift your arm.","body":"Skeletal muscle is voluntary: the command starts in the brain and travels along motor neurons.","lensCaption":"A signal leaving the brain","scene":"nerve","path":[[250,60]],"lens":[{"x":14,"y":50,"w":18,"h":18,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":36,"y":50,"w":14,"h":14,"r":"50%","bg":"#b07aa0","border":"none","o":0.6}]},{"short":"Nerve","place":"Spinal cord and nerve","view":"body","organs":["spine","nerves"],"label":[160,262,"start"],"title":"A motor neuron carries the command.","body":"The signal runs down the spinal cord and out along a motor neuron. One motor neuron and all the fibres it supplies form a motor unit, about 150 fibres on average.","lensCaption":"The impulse travelling along the axon","scene":"nerve","path":[[250,90],[250,222],[190,236],[146,296]],"lens":[{"x":30,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":0.4},{"x":54,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":0.7},{"x":78,"y":50,"w":18,"h":18,"r":"50%","bg":"#b07aa0","border":"none","o":1}]},{"short":"Junction","place":"Neuromuscular junction","view":"arm","organs":["nerves","tissues"],"label":[146,320,"start"],"title":"Acetylcholine fires the muscle cell.","body":"At the neuromuscular junction, axon terminals release acetylcholine. Sodium rushes into the muscle cell, the inside turns positive, and the cell fires its own action potential.","lensCaption":"Acetylcholine crossing to the muscle","scene":"muscle","path":[[130,320]],"lens":[{"x":50,"y":14,"w":90,"h":36,"r":"0 0 40px 40px","bg":"#e8d3e2","border":"none","o":1},{"x":34,"y":38,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":50,"y":44,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":66,"y":38,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":26,"y":70,"w":12,"h":12,"r":"50%","bg":"#e0b46a","border":"none","o":1},{"x":46,"y":76,"w":12,"h":12,"r":"50%","bg":"#e0b46a","border":"none","o":1},{"x":66,"y":70,"w":12,"h":12,"r":"50%","bg":"#e0b46a","border":"none","o":1},{"x":80,"y":80,"w":12,"h":12,"r":"50%","bg":"#e0b46a","border":"none","o":1}]},{"short":"Sliding","place":"Inside the fibre","view":"arm","organs":["tissues"],"label":[146,350,"start"],"title":"Actin slides in among myosin.","body":"Calcium binds to troponin and uncovers actin. Myosin heads link to actin (cross-bridges) and pull, using energy from ATP. The Z lines move closer and the sarcomere shortens.","analogy":"Like a team pulling a rope hand over hand.","lensCaption":"Thin actin pulled in among thick myosin","scene":"none","path":[[122,350]],"lens":[{"x":50,"y":30,"w":110,"h":12,"r":"6px","bg":"#71836d","border":"none","o":1},{"x":50,"y":50,"w":110,"h":12,"r":"6px","bg":"#71836d","border":"none","o":1},{"x":50,"y":70,"w":110,"h":12,"r":"6px","bg":"#71836d","border":"none","o":1},{"x":22,"y":40,"w":70,"h":6,"r":"3px","bg":"#c86d56","border":"none","o":1},{"x":78,"y":40,"w":70,"h":6,"r":"3px","bg":"#c86d56","border":"none","o":1},{"x":22,"y":60,"w":70,"h":6,"r":"3px","bg":"#c86d56","border":"none","o":1},{"x":78,"y":60,"w":70,"h":6,"r":"3px","bg":"#c86d56","border":"none","o":1},{"x":8,"y":50,"w":6,"h":90,"r":"3px","bg":"#243341","border":"none","o":1},{"x":92,"y":50,"w":6,"h":90,"r":"3px","bg":"#243341","border":"none","o":1},{"x":50,"y":86,"w":12,"h":12,"r":"50%","bg":"#e0b46a","border":"none","o":1}]},{"short":"Energy","place":"Blood supply","view":"arm","organs":["tissues","vessels"],"label":[150,380,"start"],"title":"The muscle needs a steady supply of ATP.","body":"ATP comes from aerobic respiration of glucose, from anaerobic breakdown (which builds up lactic acid), from phosphocreatine and from fatty acids. Heat is a by-product.","lensCaption":"Glucose and oxygen arriving from the blood","scene":"blood","path":[[134,370]],"lens":[{"x":20,"y":40,"w":14,"h":14,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":40,"y":56,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":60,"y":42,"w":14,"h":14,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":80,"y":58,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":30,"y":66,"w":12,"h":12,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":70,"y":30,"w":12,"h":12,"r":"50%","bg":"#d8c35a","border":"none","o":1}]},{"short":"Movement","place":"Arm","view":"arm","organs":["tissues","skeleton"],"label":[150,300,"start"],"title":"The muscle shortens and pulls the bone.","body":"All the fibres in the motor unit contract fully or not at all (all-or-none). Lifting a weight is isotonic: the muscle shortens while the tension stays the same.","lensCaption":"A shortened, thicker muscle","scene":"muscle","path":[[126,300]],"lens":[{"x":50,"y":50,"w":120,"h":70,"r":"50px","bg":"#8fa48a","border":"none","o":1},{"x":50,"y":18,"w":190,"h":16,"r":"8px","bg":"#e8dcb8","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9: The Muscular System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 10: Muscle Tissue","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified picture. The nerve route is drawn as one line, and the lens shows the sarcomere and junction as cartoons."},"ap-10":{"id":"ap-10","after":8,"title":"A reflex arc: pulling your finger off a thorn","token":"#b07aa0","hideCore":true,"stops":[{"short":"Receptor","place":"Fingertip","view":"arm","organs":["skin","nerves"],"label":[112,520,"start"],"title":"A receptor picks up the stimulus.","body":"You touch a thorn. Receptors in the skin turn the stimulus into a nerve impulse.","lensCaption":"Receptor firing in the skin","scene":"skin","path":[[98,528]],"lens":[{"x":50,"y":10,"w":8,"h":40,"r":"2px","bg":"#5b4636","border":"none","o":1},{"x":50,"y":52,"w":26,"h":26,"r":"50%","bg":"#fff","border":"5px solid #b07aa0","o":1},{"x":50,"y":80,"w":8,"h":40,"r":"3px","bg":"#b07aa0","border":"none","o":1}]},{"short":"Sensory","place":"Sensory neuron","view":"body","organs":["nerves","spine"],"label":[164,262,"start"],"title":"A sensory neuron carries it in.","body":"The sensory (afferent) neuron carries the impulse to the spinal cord, entering through the dorsal root. Most sensory neurons are unipolar.","lensCaption":"Depolarization moving along the axon","scene":"nerve","path":[[104,440],[146,296],[200,232],[250,222]],"lens":[{"x":20,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":0.3},{"x":44,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":0.6},{"x":68,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":88,"y":50,"w":14,"h":14,"r":"50%","bg":"#e0b46a","border":"none","o":1}]},{"short":"Spinal cord","place":"Spinal cord","view":"torso","organs":["spine"],"label":[262,222,"start"],"title":"An association neuron passes it on.","body":"In the gray matter of the spinal cord, an association (internuncial) neuron links the sensory neuron to a motor neuron. The impulse crosses each synapse in one direction only.","lensCaption":"A neurotransmitter crossing the synapse","scene":"none","path":[[250,226]],"lens":[{"x":30,"y":50,"w":70,"h":40,"r":"0 30px 30px 0","bg":"#e8d3e2","border":"none","o":1},{"x":74,"y":50,"w":50,"h":40,"r":"30px 0 0 30px","bg":"#e8d3e2","border":"none","o":1},{"x":52,"y":40,"w":8,"h":8,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":56,"y":52,"w":8,"h":8,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":50,"y":62,"w":8,"h":8,"r":"50%","bg":"#b07aa0","border":"none","o":1}]},{"short":"Motor","place":"Motor neuron","view":"body","organs":["nerves","spine"],"label":[164,300,"start"],"title":"A motor neuron carries the command out.","body":"The motor (efferent) neuron leaves through the ventral root and carries the response back out along the spinal nerve. Spinal nerves are mixed: sensory and motor.","lensCaption":"The response heading back out","scene":"nerve","path":[[250,230],[200,240],[146,296]],"lens":[{"x":80,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":0.3},{"x":56,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":0.6},{"x":32,"y":50,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":1}]},{"short":"Effector","place":"Arm muscle","view":"arm","organs":["tissues","nerves"],"label":[146,340,"start"],"title":"The muscle pulls your hand away.","body":"The effector organ, here a muscle, contracts. A reflex is involuntary and faster than a thought-out response.","lensCaption":"Muscle fibres contracting","scene":"muscle","path":[[124,330]],"lens":[{"x":50,"y":50,"w":130,"h":60,"r":"40px","bg":"#8fa48a","border":"none","o":1},{"x":24,"y":50,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1}]},{"short":"Brain","place":"Up to the brain","view":"body","organs":["spine","brain"],"label":[276,62,"start"],"title":"Then the brain finds out.","body":"The spinal cord also carries sensory impulses up to the brain, so you also become aware of the prick.","lensCaption":"The message arriving in the brain","scene":"none","path":[[146,296],[250,222],[250,84],[250,62]],"lens":[{"x":50,"y":50,"w":150,"h":110,"r":"46% 54% 50% 50%","bg":"#e3b9b0","border":"none","o":1},{"x":40,"y":40,"w":16,"h":16,"r":"50%","bg":"#b07aa0","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10: The Nervous System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 13: Anatomy of the Nervous System","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified reflex arc. One nerve line stands for many neurons, and the dorsal and ventral roots are not drawn separately."},"ap-12":{"id":"ap-12","after":3,"title":"Follow a hormone signal through the endocrine system","token":"#b07aa0","hideCore":true,"stops":[{"short":"Hypothalamus","place":"Hypothalamus","view":"head","organs":["brain","pituitary"],"label":[262,70,"start"],"title":"The hypothalamus gives the first order.","body":"Neurons in the hypothalamus make releasing hormones, such as thyrotropin-releasing hormone (TRH). They travel through a portal vein down the infundibulum to the anterior pituitary.","lensCaption":"Releasing hormone heading to the pituitary","scene":"none","path":[[250,70]],"lens":[{"x":50,"y":40,"w":120,"h":80,"r":"46% 54% 50% 50%","bg":"#e3b9b0","border":"none","o":1},{"x":50,"y":80,"w":8,"h":40,"r":"4px","bg":"#c99ab8","border":"none","o":1},{"x":48,"y":58,"w":14,"h":14,"r":"30%","bg":"#b07aa0","border":"none","o":1},{"x":54,"y":70,"w":14,"h":14,"r":"30%","bg":"#b07aa0","border":"none","o":1}]},{"short":"Pituitary","place":"Anterior pituitary","view":"head","organs":["pituitary"],"label":[262,86,"start"],"title":"The pituitary releases TSH into the blood.","body":"The pea-sized anterior pituitary answers with thyroid-stimulating hormone (TSH). Endocrine glands are ductless: hormones go straight into the bloodstream.","lensCaption":"TSH entering a capillary","scene":"blood","path":[[250,84]],"lens":[{"x":20,"y":46,"w":14,"h":14,"r":"30%","bg":"#b07aa0","border":"none","o":1},{"x":36,"y":56,"w":14,"h":14,"r":"30%","bg":"#b07aa0","border":"none","o":1},{"x":54,"y":44,"w":14,"h":14,"r":"30%","bg":"#b07aa0","border":"none","o":1},{"x":70,"y":58,"w":14,"h":14,"r":"30%","bg":"#b07aa0","border":"none","o":1},{"x":30,"y":34,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":78,"y":40,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":60,"y":66,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1}]},{"short":"Thyroid","place":"Thyroid","view":"neck","organs":["thyroid","vessels"],"label":[270,166,"start"],"title":"The thyroid makes T3 and T4.","body":"TSH reaches its target organ. The thyroid uses iodine to make thyroxine (T4) and triiodothyronine (T3), which regulate metabolism.","lensCaption":"TSH binding to thyroid cell receptors","scene":"none","path":[[250,150],[250,166]],"lens":[{"x":50,"y":64,"w":170,"h":60,"r":"30px","bg":"#e9c3cf","border":"none","o":1},{"x":26,"y":46,"w":22,"h":12,"r":"12px 12px 0 0","bg":"#71836d","border":"none","o":1},{"x":50,"y":46,"w":22,"h":12,"r":"12px 12px 0 0","bg":"#71836d","border":"none","o":1},{"x":74,"y":46,"w":22,"h":12,"r":"12px 12px 0 0","bg":"#71836d","border":"none","o":1},{"x":26,"y":32,"w":14,"h":14,"r":"30%","bg":"#b07aa0","border":"none","o":1},{"x":50,"y":32,"w":14,"h":14,"r":"30%","bg":"#b07aa0","border":"none","o":1},{"x":74,"y":22,"w":14,"h":14,"r":"30%","bg":"#b07aa0","border":"none","o":1},{"x":40,"y":74,"w":10,"h":10,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":60,"y":74,"w":10,"h":10,"r":"50%","bg":"#d3a84b","border":"none","o":1}]},{"short":"Feedback","place":"Back to the brain","view":"head","organs":["thyroid","pituitary","brain"],"label":[262,78,"start"],"title":"Negative feedback turns it down.","body":"As thyroid hormone rises, it inhibits TSH from the pituitary and TRH from the hypothalamus. Secretion drops, keeping levels in a narrow range.","analogy":"Like a thermostat switching the heat off once the room is warm.","lensCaption":"Thyroid hormone signalling “enough”","scene":"none","path":[[250,140],[250,84]],"lens":[{"x":30,"y":40,"w":14,"h":14,"r":"30%","bg":"#d3a84b","border":"none","o":1},{"x":50,"y":30,"w":14,"h":14,"r":"30%","bg":"#d3a84b","border":"none","o":1},{"x":70,"y":40,"w":14,"h":14,"r":"30%","bg":"#d3a84b","border":"none","o":1},{"x":50,"y":66,"w":60,"h":8,"r":"4px","bg":"#c86d56","border":"none","o":1}]},{"short":"Adrenals","place":"Adrenal glands","view":"torso","organs":["adrenals","kidneys"],"label":[330,320,"start"],"title":"The adrenals handle stress and salt.","body":"On top of the kidneys, the adrenal medulla releases epinephrine for fight or flight. The cortex makes aldosterone (sodium and potassium) and cortisol (raises blood glucose).","lensCaption":"Epinephrine released into the blood","scene":"blood","path":[[250,200],[256,300],[314,322]],"lens":[{"x":20,"y":40,"w":14,"h":14,"r":"30%","bg":"#e0a83a","border":"none","o":1},{"x":36,"y":56,"w":14,"h":14,"r":"30%","bg":"#e0a83a","border":"none","o":1},{"x":52,"y":42,"w":14,"h":14,"r":"30%","bg":"#e0a83a","border":"none","o":1},{"x":68,"y":58,"w":14,"h":14,"r":"30%","bg":"#e0a83a","border":"none","o":1},{"x":84,"y":44,"w":14,"h":14,"r":"30%","bg":"#e0a83a","border":"none","o":1},{"x":30,"y":70,"w":24,"h":14.879999999999999,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":70,"y":30,"w":24,"h":14.879999999999999,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1}]},{"short":"Pancreas","place":"Pancreas","view":"torso","organs":["pancreas","liver"],"label":[318,364,"start"],"title":"Insulin and glucagon balance blood glucose.","body":"In the islets of Langerhans, beta cells release insulin after a meal, moving glucose into cells and lowering blood glucose. Alpha cells release glucagon when glucose falls, so the liver releases glucose.","lensCaption":"Insulin helping glucose into a cell","scene":"none","path":[[300,330],[272,358]],"lens":[{"x":50,"y":74,"w":170,"h":60,"r":"30px","bg":"#efe1c3","border":"none","o":1},{"x":30,"y":56,"w":22,"h":12,"r":"12px 12px 0 0","bg":"#71836d","border":"none","o":1},{"x":70,"y":56,"w":22,"h":12,"r":"12px 12px 0 0","bg":"#71836d","border":"none","o":1},{"x":30,"y":40,"w":14,"h":14,"r":"30%","bg":"#dcb25a","border":"none","o":1},{"x":70,"y":40,"w":14,"h":14,"r":"30%","bg":"#dcb25a","border":"none","o":1},{"x":44,"y":34,"w":12,"h":12,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":56,"y":24,"w":12,"h":12,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":50,"y":80,"w":12,"h":12,"r":"50%","bg":"#d8c35a","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12: The Endocrine System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 17: The Endocrine System","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified picture of one feedback loop and a few other glands. Hormones really spread through the whole bloodstream; the route shows where they act."},"ap-13":{"id":"ap-13","after":1,"title":"The life of a red blood cell","token":"#c8524a","hideCore":true,"stops":[{"short":"Marrow","place":"Red bone marrow","view":"pelvis","organs":["marrow","skeleton"],"label":[288,476,"start"],"form":"single","title":"Blood cells are made in red marrow.","body":"Making blood cells is hematopoiesis. All of them come from stem cells called hematocytoblasts. Red cells lose their nuclei as they mature, so they can’t divide.","lensCaption":"New cells forming from stem cells","scene":"osteon","path":[[226,490]],"lens":[{"x":30,"y":40,"w":40,"h":40,"r":"50%","bg":"#f4f0f8","border":"3px solid #c99ab8","o":1},{"x":62,"y":30,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":70,"y":62,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":36,"y":72,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #b07aa0","o":1},{"x":84,"y":40,"w":12,"h":8,"r":"40%","bg":"#e0b46a","border":"none","o":1},{"x":52,"y":84,"w":12,"h":8,"r":"40%","bg":"#e0b46a","border":"none","o":1}]},{"short":"Plasma","place":"In the blood","view":"torso","organs":["vessels","heart"],"label":[262,300,"start"],"title":"It joins the plasma and formed elements.","body":"Plasma is about 55% of blood; formed elements about 45%. Red cells make up about 95% of the blood cells, with 700 times more red cells than white.","lensCaption":"Red cells, a white cell and platelets in plasma","scene":"blood","path":[[244,470],[244,380],[246,240]],"lens":[{"x":20,"y":38,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":40,"y":56,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":62,"y":40,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":82,"y":58,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":30,"y":74,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":70,"y":74,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":52,"y":26,"w":26,"h":26,"r":"50%","bg":"#f4f0f8","border":"3px solid #b07aa0","o":1},{"x":14,"y":60,"w":12,"h":8,"r":"40%","bg":"#e0b46a","border":"none","o":1},{"x":88,"y":36,"w":12,"h":8,"r":"40%","bg":"#e0b46a","border":"none","o":1}]},{"short":"Lungs","place":"Lungs","view":"chest","organs":["lungs","heart"],"label":[318,246,"start"],"title":"Hemoglobin picks up oxygen.","body":"Hemoglobin fills about a third of the cell. Its heme part has four iron atoms that bind oxygen in the lungs, turning the blood bright red.","analogy":"Like a bus with four seats for oxygen.","lensCaption":"Oxygen loading onto hemoglobin","scene":"alveoli","path":[[262,230],[292,250]],"lens":[{"x":50,"y":56,"w":70,"h":43.4,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":36,"y":52,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":46,"y":46,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":56,"y":46,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":66,"y":52,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":22,"y":24,"w":12,"h":12,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":78,"y":22,"w":12,"h":12,"r":"50%","bg":"#6f91a2","border":"none","o":1}]},{"short":"Tissues","place":"Body tissues","view":"legs","organs":["vessels","tissues"],"label":[226,660,"start"],"title":"It delivers oxygen and collects carbon dioxide.","body":"Blood carries oxygen to the cells and carbon dioxide back to the lungs. Globin, the protein part of hemoglobin, carries carbon dioxide. Without oxygen, blood is darker red.","lensCaption":"Oxygen out, carbon dioxide in","scene":"blood","path":[[270,226],[262,244],[256,470],[206,640],[194,660]],"lens":[{"x":50,"y":50,"w":70,"h":43.4,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":40,"y":50,"w":14,"h":14,"r":"50%","bg":"#9a9aa0","border":"none","o":1},{"x":60,"y":50,"w":14,"h":14,"r":"50%","bg":"#9a9aa0","border":"none","o":1},{"x":20,"y":22,"w":12,"h":12,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":80,"y":24,"w":12,"h":12,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":26,"y":82,"w":12,"h":12,"r":"50%","bg":"#6f91a2","border":"none","o":1}]},{"short":"Defence","place":"White blood cells","view":"legs","organs":["vessels","tissues"],"label":[226,700,"start"],"title":"White blood cells guard against infection.","body":"Leukocytes leave the blood by ameboid movement and eat microbes by phagocytosis. Neutrophils are the most numerous; lymphocytes are next.","lensCaption":"A white cell engulfing bacteria","scene":"none","path":[[200,700]],"lens":[{"x":46,"y":50,"w":80,"h":80,"r":"50%","bg":"#f4f0f8","border":"3px solid #b07aa0","o":1},{"x":74,"y":36,"w":14,"h":8,"r":"999px","bg":"#8fa48a","border":"none","o":1},{"x":80,"y":58,"w":14,"h":8,"r":"999px","bg":"#8fa48a","border":"none","o":1},{"x":54,"y":48,"w":12,"h":7,"r":"999px","bg":"#8fa48a","border":"none","o":1}]},{"short":"Clotting","place":"A cut","view":"arm","organs":["skin","vessels"],"label":[126,330,"start"],"title":"Platelets and fibrin seal a cut.","body":"Platelets clump at the cut. With calcium, prothrombin becomes thrombin, and thrombin turns fibrinogen into fibrin threads that trap cells: the clot. Vitamin K is needed for many clotting factors.","lensCaption":"Fibrin threads trapping red cells","scene":"none","path":[[244,380],[246,240],[150,250],[112,330]],"lens":[{"x":50,"y":30,"w":180,"h":3,"r":"2px","bg":"#e0b46a","border":"none","o":1},{"x":50,"y":50,"w":190,"h":3,"r":"2px","bg":"#e0b46a","border":"none","o":1},{"x":50,"y":70,"w":180,"h":3,"r":"2px","bg":"#e0b46a","border":"none","o":1},{"x":30,"y":40,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":62,"y":58,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":44,"y":72,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":70,"y":32,"w":12,"h":8,"r":"40%","bg":"#e0b46a","border":"none","o":1},{"x":24,"y":62,"w":12,"h":8,"r":"40%","bg":"#e0b46a","border":"none","o":1},{"x":82,"y":72,"w":12,"h":8,"r":"40%","bg":"#e0b46a","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13: The Blood"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 18: The Cardiovascular System: Blood","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified picture. One red cell can’t do everything shown; the white cell and clotting stops show other parts of the blood at work."},"ap-14":{"id":"ap-14","after":5,"title":"One trip around the circulation","token":"#c8524a","hideCore":true,"stops":[{"short":"Veins","place":"Vena cava","view":"torso","organs":["vessels","heart"],"label":[236,300,"end"],"title":"Blood returns through the venae cavae.","body":"Deoxygenated blood from the lower body comes up the inferior vena cava; from the head and arms, the superior vena cava. Both empty into the right atrium.","lensCaption":"Darker, oxygen-poor blood heading home","scene":"vessel","path":[[244,470],[244,380],[246,250]],"lens":[{"x":20,"y":46,"w":30,"h":18.6,"r":"50%","bg":"#8e3b37","border":"3px solid #b5605a","o":1},{"x":42,"y":56,"w":30,"h":18.6,"r":"50%","bg":"#8e3b37","border":"3px solid #b5605a","o":1},{"x":64,"y":44,"w":30,"h":18.6,"r":"50%","bg":"#8e3b37","border":"3px solid #b5605a","o":1},{"x":86,"y":54,"w":30,"h":18.6,"r":"50%","bg":"#8e3b37","border":"3px solid #b5605a","o":1},{"x":30,"y":30,"w":14,"h":14,"r":"50%","bg":"#9a9aa0","border":"none","o":1},{"x":70,"y":66,"w":14,"h":14,"r":"50%","bg":"#9a9aa0","border":"none","o":1}]},{"short":"Right side","place":"Right atrium and ventricle","view":"chest","organs":["heart"],"label":[296,206,"start"],"title":"The right side pumps blood to the lungs.","body":"From the right atrium, blood passes the tricuspid valve into the right ventricle, then out through the pulmonary semilunar valve into the pulmonary arteries.","analogy":"Valves are one-way doors.","lensCaption":"Blood through the tricuspid valve","scene":"none","path":[[262,232],[262,222]],"lens":[{"x":50,"y":30,"w":150,"h":60,"r":"40px","bg":"#e9b5a8","border":"none","o":1},{"x":50,"y":72,"w":150,"h":60,"r":"40px","bg":"#e09c88","border":"none","o":1},{"x":36,"y":52,"w":40,"h":8,"r":"4px","bg":"#fff","border":"none","o":1},{"x":64,"y":52,"w":40,"h":8,"r":"4px","bg":"#fff","border":"none","o":1},{"x":50,"y":70,"w":28,"h":17.36,"r":"50%","bg":"#8e3b37","border":"3px solid #b5605a","o":1}]},{"short":"Lungs","place":"Lungs","view":"chest","organs":["lungs"],"label":[318,262,"start"],"title":"In the lungs, blood swaps gases.","body":"Pulmonary circulation runs from the right ventricle to the lungs and back to the left atrium. In the lungs, blood drops carbon dioxide and picks up oxygen.","lensCaption":"Carbon dioxide out, oxygen in","scene":"alveoli","path":[[280,236],[298,250]],"lens":[{"x":40,"y":60,"w":50,"h":31,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":30,"y":58,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":46,"y":52,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":70,"y":30,"w":14,"h":14,"r":"50%","bg":"#9a9aa0","border":"none","o":1},{"x":80,"y":44,"w":14,"h":14,"r":"50%","bg":"#9a9aa0","border":"none","o":1},{"x":18,"y":26,"w":12,"h":12,"r":"50%","bg":"#6f91a2","border":"none","o":1}]},{"short":"Left side","place":"Left atrium and ventricle","view":"chest","organs":["heart"],"label":[296,236,"start"],"title":"The left side pumps to the whole body.","body":"Four pulmonary veins bring oxygenated blood to the left atrium. It passes the bicuspid (mitral) valve into the left ventricle, which has the thickest wall because it pumps at high pressure.","lensCaption":"Bright red blood in the left ventricle","scene":"none","path":[[286,240],[276,232]],"lens":[{"x":50,"y":50,"w":160,"h":120,"r":"50px","bg":"#c86d56","border":"none","o":1},{"x":50,"y":50,"w":110,"h":74,"r":"40px","bg":"#f6e1da","border":"none","o":1},{"x":40,"y":46,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":60,"y":56,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1}]},{"short":"Aorta","place":"Aorta and arteries","view":"torso","organs":["vessels"],"label":[276,380,"start"],"title":"The aorta sends blood out to the organs.","body":"The left ventricle pumps through the aortic semilunar valve into the aorta, the largest artery. Systemic circulation takes oxygenated blood to every organ.","lensCaption":"Oxygen-rich blood under pressure","scene":"blood","path":[[262,244],[262,330],[258,400],[256,470]],"lens":[{"x":16,"y":44,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":38,"y":58,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":60,"y":42,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":82,"y":56,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":28,"y":30,"w":10,"h":10,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":70,"y":70,"w":10,"h":10,"r":"50%","bg":"#6f91a2","border":"none","o":1}]},{"short":"Capillaries","place":"Capillaries in the leg","view":"legs","organs":["vessels","tissues"],"label":[226,660,"start"],"title":"Capillaries are where the exchange happens.","body":"Arterioles feed capillaries, which are one cell thick. Nutrients, gases and wastes pass between blood and tissues there. Venules then carry blood into veins, whose valves keep it moving toward the heart.","lensCaption":"Red cells passing single file","scene":"vessel","path":[[240,540],[214,620],[196,660]],"lens":[{"x":20,"y":50,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":42,"y":50,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":64,"y":50,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":86,"y":50,"w":26,"h":16.12,"r":"50%","bg":"#8e3b37","border":"3px solid #b5605a","o":1},{"x":40,"y":20,"w":10,"h":10,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":60,"y":80,"w":10,"h":10,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":80,"y":22,"w":10,"h":10,"r":"50%","bg":"#9a9aa0","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14: The Cardiovascular Circulatory System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapters 19 and 20: The Heart; Blood Vessels and Circulation","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified loop. The heart is drawn as one shape, so the chambers are described rather than shown, and the vessels are single lines."},"ap-15":{"id":"ap-15","after":2,"title":"Follow lymph back to the blood","token":"#6f91a2","hideCore":true,"dim":0.3,"stops":[{"short":"Tissues","place":"Leg tissues","view":"legs","organs":["tissues","vessels"],"label":[226,660,"start"],"title":"Plasma leaks out and becomes lymph.","body":"Blood pressure pushes some plasma out of capillaries; between the cells it’s interstitial fluid. What isn’t reabsorbed enters blind-ended lymphatic capillaries and is now called lymph.","analogy":"Like a drain that catches water the pipes leak.","lensCaption":"Fluid entering a lymphatic capillary","scene":"none","path":[[194,660]],"lens":[{"x":50,"y":74,"w":180,"h":30,"r":"40px","bg":"#dde8ed","border":"3px solid #6f91a2","o":1},{"x":24,"y":30,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":44,"y":22,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":64,"y":34,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":80,"y":24,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":36,"y":48,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":58,"y":52,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":20,"y":54,"w":22,"h":13.64,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1}]},{"short":"Vessels","place":"Lymphatic vessels","view":"legs","organs":["lymphnodes"],"label":[226,560,"start"],"title":"Valves keep lymph moving one way.","body":"Lymphatics look like veins but have thinner walls and more valves. Skeletal muscle contractions, breathing and smooth muscle in the walls push the lymph along. A blockage causes edema.","lensCaption":"Lymph flowing past a valve","scene":"vessel","path":[[200,600],[212,520]],"lens":[{"x":18,"y":50,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":36,"y":44,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":54,"y":56,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":72,"y":48,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":88,"y":38,"w":20,"h":6,"r":"3px","bg":"#6f91a2","border":"none","o":1},{"x":88,"y":62,"w":20,"h":6,"r":"3px","bg":"#6f91a2","border":"none","o":1}]},{"short":"Node","place":"Lymph node","view":"pelvis","organs":["lymphnodes"],"label":[226,522,"start"],"title":"Lymph nodes filter it.","body":"Nodes cluster in the groin, armpits and neck. Inside, macrophages clean up microbes by phagocytosis and germinal centres make lymphocytes. Swollen nodes usually mean an infection.","lensCaption":"Macrophages and lymphocytes at work","scene":"none","path":[[212,520]],"lens":[{"x":50,"y":50,"w":200,"h":150,"r":"50%","bg":"#e6eef2","border":"4px solid #9fb6c2","o":1},{"x":30,"y":40,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":50,"y":34,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":70,"y":44,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":40,"y":64,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":64,"y":66,"w":40,"h":36,"r":"40% 60% 50% 50%","bg":"#c8d9e0","border":"3px solid #6f91a2","o":1},{"x":76,"y":62,"w":10,"h":6,"r":"999px","bg":"#8fa48a","border":"none","o":1}]},{"short":"Lacteals","place":"Small intestine","view":"gut","organs":["intestine","lymph"],"label":[300,440,"start"],"title":"Lacteals pick up fats.","body":"In the small intestine, special lymphatic vessels called lacteals absorb fats. The milky, fat-filled lymph there is called chyle.","lensCaption":"Fat drops entering a lacteal","scene":"villi","path":[[240,440],[262,440]],"lens":[{"x":30,"y":30,"w":16,"h":16,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":50,"y":24,"w":16,"h":16,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":70,"y":32,"w":16,"h":16,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":40,"y":50,"w":12,"h":12,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":60,"y":52,"w":12,"h":12,"r":"50%","bg":"#d3a84b","border":"none","o":1}]},{"short":"Thoracic duct","place":"Thoracic duct","view":"torso","organs":["lymph","vessels"],"label":[226,330,"end"],"title":"The thoracic duct returns lymph to the blood.","body":"Lymph from most of the body collects in the thoracic duct, which empties into the left subclavian vein. The right lymphatic duct empties into the right subclavian vein.","lensCaption":"Lymph rejoining the bloodstream","scene":"vessel","path":[[250,430],[240,400],[238,330],[236,250],[252,214]],"lens":[{"x":16,"y":50,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":32,"y":46,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":48,"y":54,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":70,"y":48,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":88,"y":54,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1}]},{"short":"Spleen","place":"Spleen","view":"torso","organs":["spleen"],"label":[350,302,"start"],"title":"The spleen filters the blood.","body":"The spleen, in the upper left abdomen, is the largest mass of lymphatic tissue. It destroys bacteria and worn-out red cells and platelets, makes lymphocytes and stores blood.","lensCaption":"Old red cells being cleared","scene":"none","path":[[300,230],[336,300]],"lens":[{"x":50,"y":50,"w":200,"h":160,"r":"50%","bg":"#ead1d8","border":"none","o":1},{"x":36,"y":40,"w":28,"h":17.36,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":62,"y":56,"w":32,"h":20,"r":"40%","bg":"#b98a84","border":"none","o":0.7},{"x":70,"y":34,"w":26,"h":26,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":30,"y":68,"w":40,"h":36,"r":"40% 60% 50% 50%","bg":"#d6b5bd","border":"3px solid #8e5a6a","o":1}]},{"short":"Thymus","place":"Thymus","view":"neck","organs":["thymus"],"label":[268,192,"start"],"title":"T cells mature in the thymus.","body":"The two-lobed thymus in the mediastinum is where T lymphocytes mature. T cells give cellular immunity; B cells make antibodies. The thymus is largest at puberty, then shrinks.","lensCaption":"T cells maturing","scene":"none","path":[[300,240],[250,196]],"lens":[{"x":26,"y":36,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":50,"y":28,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":74,"y":38,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":36,"y":62,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":62,"y":64,"w":30,"h":30,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1},{"x":50,"y":84,"w":26,"h":26,"r":"50%","bg":"#f4f0f8","border":"3px solid #6f91a2","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 15: The Lymphatic Circulatory System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 21: The Lymphatic and Immune System","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified picture. Only a few lymph nodes and vessels are drawn, and the route jumps between organs to show each one’s job."},"ap-16":{"id":"ap-16","after":1,"title":"Follow a bite of food through the digestive tract","token":"#b9875a","stops":[{"short":"Mouth","place":"Mouth","view":"head","organs":["mouth","salivary"],"label":[284,124,"start"],"form":"drop","title":"Chewing and saliva start the work.","body":"Teeth break food apart (mastication). Saliva from the parotid, submandibular and sublingual glands wets it, and salivary amylase starts breaking down starch.","analogy":"Like cutting food up and adding a splash of water before it goes in the pot.","lensCaption":"Food pieces, saliva and amylase","scene":"none","path":[[250,122]],"lens":[{"x":50,"y":50,"w":90,"h":72,"r":"42% 58% 50% 46%","bg":"#b9875a","border":"none","o":1},{"x":22,"y":26,"w":28,"h":22.400000000000002,"r":"42% 58% 50% 46%","bg":"#e6cfa8","border":"none","o":1},{"x":78,"y":26,"w":24,"h":19.200000000000003,"r":"42% 58% 50% 46%","bg":"#b9875a","border":"none","o":1},{"x":24,"y":76,"w":26,"h":20.8,"r":"42% 58% 50% 46%","bg":"#b9875a","border":"none","o":1},{"x":78,"y":76,"w":30,"h":24,"r":"42% 58% 50% 46%","bg":"#e6cfa8","border":"none","o":1},{"x":40,"y":18,"w":12,"h":12,"r":"50%","bg":"#bcd4de","border":"none","o":1},{"x":64,"y":84,"w":12,"h":12,"r":"50%","bg":"#bcd4de","border":"none","o":1},{"x":14,"y":50,"w":12,"h":12,"r":"50%","bg":"#bcd4de","border":"none","o":1},{"x":84,"y":50,"w":16,"h":10,"r":"6px","bg":"#c86d56","border":"none","o":1},{"x":54,"y":12,"w":16,"h":10,"r":"6px","bg":"#c86d56","border":"none","o":1}]},{"short":"Esophagus","place":"Esophagus","view":"torso","organs":["esophagus"],"label":[268,190,"start"],"form":"drop","title":"Swallowing pushes the bolus down.","body":"The tongue shapes a bolus and the epiglottis seals the airway (deglutition). Peristalsis carries it down the 10-inch esophagus to the lower esophageal sphincter.","analogy":"Like squeezing toothpaste along the tube.","lensCaption":"Muscle waves squeeze the bolus along","scene":"muscle","path":[[250,140],[250,190],[251,232],[257,265]],"lens":[{"x":50,"y":50,"w":96,"h":80,"r":"46% 54% 48% 52%","bg":"#b9875a","border":"none","o":1},{"x":50,"y":12,"w":120,"h":10,"r":"6px","bg":"#c9b9a0","border":"none","o":1},{"x":50,"y":88,"w":120,"h":10,"r":"6px","bg":"#c9b9a0","border":"none","o":1}]},{"short":"Stomach","place":"Stomach","view":"gut","organs":["stomach"],"label":[326,300,"start"],"form":"small","title":"The stomach churns food into chyme.","body":"Three muscle layers churn the food. Parietal cells release hydrochloric acid, which turns pepsinogen from chief cells into pepsin to start protein digestion. It empties in 2 to 6 hours.","analogy":"Like a mixer with a small door at the bottom.","lensCaption":"Acid and pepsin go to work on protein","scene":"swirl","path":[[264,282],[280,300],[290,314]],"lens":[{"x":40,"y":40,"w":50,"h":40,"r":"42% 58% 50% 46%","bg":"#b9875a","border":"none","o":1},{"x":64,"y":62,"w":40,"h":32,"r":"42% 58% 50% 46%","bg":"#e6cfa8","border":"none","o":1},{"x":30,"y":66,"w":30,"h":24,"r":"42% 58% 50% 46%","bg":"#b9875a","border":"none","o":1},{"x":70,"y":30,"w":12,"h":12,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":22,"y":36,"w":12,"h":12,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":54,"y":80,"w":12,"h":12,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":58,"y":28,"w":16,"h":10,"r":"6px","bg":"#c86d56","border":"none","o":1},{"x":80,"y":52,"w":16,"h":10,"r":"6px","bg":"#c86d56","border":"none","o":1},{"x":36,"y":82,"w":16,"h":10,"r":"6px","bg":"#c86d56","border":"none","o":1}]},{"short":"Bile","place":"Liver + gallbladder","view":"gut","organs":["liver","gallbladder"],"label":[196,300,"end"],"form":"small","title":"Bile breaks fat into small drops.","body":"The liver makes bile salts and the gallbladder stores and concentrates them. Bile flows through the common bile duct into the duodenum, where it emulsifies fats.","analogy":"Like dish soap breaking up grease.","lensCaption":"Fat drops coated in bile","scene":"none","path":[[276,336],[256,338],[238,340]],"lens":[{"x":30,"y":30,"w":26,"h":26,"r":"50%","bg":"#d3a84b","border":"3px solid #71836d","o":1},{"x":52,"y":22,"w":26,"h":26,"r":"50%","bg":"#d3a84b","border":"3px solid #71836d","o":1},{"x":72,"y":34,"w":26,"h":26,"r":"50%","bg":"#d3a84b","border":"3px solid #71836d","o":1},{"x":24,"y":54,"w":26,"h":26,"r":"50%","bg":"#d3a84b","border":"3px solid #71836d","o":1},{"x":46,"y":48,"w":26,"h":26,"r":"50%","bg":"#d3a84b","border":"3px solid #71836d","o":1},{"x":70,"y":58,"w":26,"h":26,"r":"50%","bg":"#d3a84b","border":"3px solid #71836d","o":1},{"x":34,"y":74,"w":26,"h":26,"r":"50%","bg":"#d3a84b","border":"3px solid #71836d","o":1},{"x":56,"y":78,"w":26,"h":26,"r":"50%","bg":"#d3a84b","border":"3px solid #71836d","o":1},{"x":78,"y":76,"w":26,"h":26,"r":"50%","bg":"#d3a84b","border":"3px solid #71836d","o":1}]},{"short":"Pancreas","place":"Pancreas","view":"gut","organs":["pancreas"],"label":[318,364,"start"],"form":"small","title":"Pancreatic juice brings the enzymes.","body":"The pancreas sends lipases, carbohydrases and proteases through the pancreatic duct, with sodium bicarbonate to neutralize the acid chyme.","analogy":"Like a toolkit with a different tool for each kind of food.","lensCaption":"Enzymes cut food into small pieces","scene":"none","path":[[232,354],[240,368]],"lens":[{"x":26,"y":30,"w":30,"h":24,"r":"42% 58% 50% 46%","bg":"#b9875a","border":"none","o":1},{"x":66,"y":26,"w":28,"h":22.400000000000002,"r":"42% 58% 50% 46%","bg":"#e6cfa8","border":"none","o":1},{"x":44,"y":62,"w":30,"h":24,"r":"42% 58% 50% 46%","bg":"#b9875a","border":"none","o":1},{"x":46,"y":30,"w":16,"h":10,"r":"6px","bg":"#c86d56","border":"none","o":1},{"x":78,"y":48,"w":16,"h":10,"r":"6px","bg":"#c86d56","border":"none","o":1},{"x":22,"y":58,"w":16,"h":10,"r":"6px","bg":"#c86d56","border":"none","o":1},{"x":66,"y":74,"w":16,"h":10,"r":"6px","bg":"#c86d56","border":"none","o":1},{"x":30,"y":82,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":84,"y":24,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":56,"y":48,"w":10,"h":10,"r":"50%","bg":"#e6cfa8","border":"none","o":1}]},{"short":"Small intestine","place":"Small intestine","view":"gut","organs":["intestine"],"label":[304,420,"start"],"form":"single","title":"Most nutrients are absorbed here.","body":"About 80% of absorption happens in the 21-foot small intestine: duodenum, jejunum and ileum. Villi pass sugars and amino acids into capillaries, and fats into lacteals.","analogy":"Folds, villi and microvilli are like a towel’s loops: lots of surface in a small space.","lensCaption":"Nutrients moving into the villi","scene":"villi","path":[[262,374],[284,390],[270,404],[236,404],[214,414],[228,428],[262,430],[288,446],[270,458],[228,460],[220,478],[264,476]],"lens":[{"x":20,"y":30,"w":12,"h":12,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":40,"y":22,"w":12,"h":12,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":60,"y":34,"w":12,"h":12,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":80,"y":24,"w":12,"h":12,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":30,"y":48,"w":10,"h":10,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":52,"y":50,"w":10,"h":10,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":72,"y":48,"w":10,"h":10,"r":"50%","bg":"#d8c35a","border":"none","o":1},{"x":10,"y":70,"w":9,"h":9,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":90,"y":72,"w":9,"h":9,"r":"50%","bg":"#d3a84b","border":"none","o":1},{"x":50,"y":72,"w":9,"h":9,"r":"50%","bg":"#d8c35a","border":"none","o":1}]},{"short":"Large intestine","place":"Large intestine","view":"gut","organs":["colon"],"label":[318,430,"start"],"form":"single","title":"Water is taken back, then waste leaves.","body":"The 5-foot large intestine absorbs water. Its bacteria make vitamin K, biotin and vitamin B5. Mass peristalsis moves feces into the rectum, triggering the defecation reflex.","lensCaption":"Gut bacteria and leftover fibre","scene":"colon","path":[[268,480],[214,486],[190,460],[190,402],[208,384],[294,384],[312,402],[312,470],[292,492]],"lens":[{"x":26,"y":30,"w":22,"h":12,"r":"999px","bg":"#8fa48a","border":"none","o":1},{"x":62,"y":24,"w":20,"h":11,"r":"999px","bg":"#b07aa0","border":"none","o":1},{"x":78,"y":52,"w":22,"h":12,"r":"999px","bg":"#8fa48a","border":"none","o":1},{"x":40,"y":58,"w":20,"h":11,"r":"999px","bg":"#d3a84b","border":"none","o":1},{"x":22,"y":74,"w":18,"h":10,"r":"999px","bg":"#b07aa0","border":"none","o":1},{"x":64,"y":78,"w":22,"h":12,"r":"999px","bg":"#8fa48a","border":"none","o":1},{"x":48,"y":38,"w":40,"h":8,"r":"6px","bg":"#c9b18a","border":"none","o":1},{"x":30,"y":88,"w":36,"h":8,"r":"6px","bg":"#c9b18a","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 16"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 23: The Digestive System","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified picture. Organs are placed to show the route, not their exact size or position, and the times and lengths are the textbook’s averages."},"ap-17":{"id":"ap-17","after":0,"title":"Follow a breath of air in and out","token":"#6f91a2","hideCore":true,"stops":[{"short":"Nose","place":"Nose","view":"head","organs":["nose"],"label":[268,100,"start"],"title":"The nose warms, moistens and filters.","body":"Air enters the nostrils. Hairs in the vestibules filter large particles, and the conchae and mucous lining warm and moisten the air. Olfactory receptors detect smells.","lensCaption":"Hairs and mucus catching dust","scene":"none","path":[[250,104]],"lens":[{"x":20,"y":50,"w":4,"h":80,"r":"2px","bg":"#7a6a5a","border":"none","o":1},{"x":40,"y":50,"w":4,"h":90,"r":"2px","bg":"#7a6a5a","border":"none","o":1},{"x":60,"y":50,"w":4,"h":80,"r":"2px","bg":"#7a6a5a","border":"none","o":1},{"x":80,"y":50,"w":4,"h":90,"r":"2px","bg":"#7a6a5a","border":"none","o":1},{"x":30,"y":30,"w":8,"h":8,"r":"50%","bg":"#9a8f7e","border":"none","o":1},{"x":50,"y":60,"w":8,"h":8,"r":"50%","bg":"#9a8f7e","border":"none","o":1},{"x":70,"y":40,"w":8,"h":8,"r":"50%","bg":"#9a8f7e","border":"none","o":1},{"x":28,"y":72,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":64,"y":24,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":84,"y":70,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1}]},{"short":"Larynx","place":"Pharynx and larynx","view":"head","organs":["trachea","mouth"],"label":[264,140,"start"],"title":"Air passes the larynx, the voice box.","body":"The pharynx carries both air and food. In the larynx, the epiglottis covers the glottis when you swallow. Air passing the true vocal cords makes them vibrate and produce sound.","lensCaption":"Air between the vocal cords","scene":"none","path":[[250,124],[250,140]],"lens":[{"x":32,"y":50,"w":20,"h":120,"r":"10px","bg":"#e7b3a3","border":"none","o":1},{"x":68,"y":50,"w":20,"h":120,"r":"10px","bg":"#e7b3a3","border":"none","o":1},{"x":50,"y":30,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":50,"y":52,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":50,"y":74,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1}]},{"short":"Trachea","place":"Trachea","view":"neck","organs":["trachea"],"label":[264,176,"start"],"title":"The trachea carries only air.","body":"The 4.5-inch windpipe is held open by 16 to 20 C-shaped rings of cartilage. Its cilia sweep mucus and dust up toward the throat.","analogy":"Like a vacuum hose with rings to stop it collapsing.","lensCaption":"Cilia sweeping mucus upward","scene":"none","path":[[250,152],[250,198]],"lens":[{"x":16,"y":86,"w":4,"h":30,"r":"2px","bg":"#e3a68c","border":"none","o":1},{"x":30,"y":86,"w":4,"h":30,"r":"2px","bg":"#e3a68c","border":"none","o":1},{"x":44,"y":86,"w":4,"h":30,"r":"2px","bg":"#e3a68c","border":"none","o":1},{"x":58,"y":86,"w":4,"h":30,"r":"2px","bg":"#e3a68c","border":"none","o":1},{"x":72,"y":86,"w":4,"h":30,"r":"2px","bg":"#e3a68c","border":"none","o":1},{"x":86,"y":86,"w":4,"h":30,"r":"2px","bg":"#e3a68c","border":"none","o":1},{"x":40,"y":60,"w":60,"h":14,"r":"8px","bg":"#e6d8a6","border":"none","o":1},{"x":46,"y":58,"w":8,"h":8,"r":"50%","bg":"#9a8f7e","border":"none","o":1},{"x":30,"y":26,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":70,"y":30,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1}]},{"short":"Bronchi","place":"Bronchial tree","view":"chest","organs":["trachea","lungs"],"label":[300,230,"start"],"title":"Air branches into the bronchial tree.","body":"The trachea splits into right and left primary bronchi, then lobar bronchi (three on the right, two on the left), segmental bronchi and bronchioles. Cartilage disappears as the branches shrink.","lensCaption":"Branches getting smaller and smaller","scene":"none","path":[[250,202],[236,216],[218,236]],"lens":[{"x":50,"y":20,"w":20,"h":40,"r":"8px","bg":"#e7c9b6","border":"none","o":1},{"x":30,"y":52,"w":14,"h":40,"r":"7px","bg":"#e7c9b6","border":"none","o":1},{"x":70,"y":52,"w":14,"h":40,"r":"7px","bg":"#e7c9b6","border":"none","o":1},{"x":18,"y":80,"w":8,"h":24,"r":"4px","bg":"#e7c9b6","border":"none","o":1},{"x":40,"y":82,"w":8,"h":24,"r":"4px","bg":"#e7c9b6","border":"none","o":1},{"x":60,"y":82,"w":8,"h":24,"r":"4px","bg":"#e7c9b6","border":"none","o":1},{"x":82,"y":80,"w":8,"h":24,"r":"4px","bg":"#e7c9b6","border":"none","o":1},{"x":50,"y":40,"w":10,"h":10,"r":"50%","bg":"#6f91a2","border":"none","o":1}]},{"short":"Alveoli","place":"Alveoli","view":"chest","organs":["lungs"],"label":[226,262,"end"],"title":"Gases cross into the blood in the alveoli.","body":"Over 300 million alveoli give about 70 square metres of surface, each wrapped in capillaries. Oxygen diffuses from the air into the blood; carbon dioxide moves the other way. This is external respiration.","lensCaption":"Oxygen in, carbon dioxide out","scene":"alveoli","path":[[210,250]],"lens":[{"x":30,"y":32,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":44,"y":40,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":66,"y":28,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":60,"y":60,"w":14,"h":14,"r":"50%","bg":"#9a9aa0","border":"none","o":1},{"x":76,"y":52,"w":14,"h":14,"r":"50%","bg":"#9a9aa0","border":"none","o":1},{"x":30,"y":70,"w":28,"h":17.36,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":54,"y":82,"w":28,"h":17.36,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":78,"y":76,"w":28,"h":17.36,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1}]},{"short":"Diaphragm","place":"Diaphragm","view":"torso","organs":["diaphragm","lungs"],"label":[350,282,"start"],"title":"The diaphragm drives each breath.","body":"Breathing in, the diaphragm contracts and moves down while the external intercostals lift the ribs. The chest gets bigger, pressure drops and air rushes in. Breathing out is mostly passive.","lensCaption":"The diaphragm contracting","scene":"muscle","path":[[226,262],[250,270]],"lens":[]},{"short":"Cells","place":"Body cells","view":"body","organs":["heart","vessels","tissues"],"label":[140,340,"start"],"title":"Blood carries oxygen to the cells.","body":"The cardiovascular system carries the gases between the lungs and the cells. Internal respiration is the exchange between the blood and body cells.","lensCaption":"Oxygen reaching a muscle cell","scene":"muscle","path":[[262,230],[300,236],[180,250],[140,300],[124,340]],"lens":[{"x":24,"y":46,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":44,"y":40,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":56,"y":52,"w":14,"h":14,"r":"50%","bg":"#6f91a2","border":"none","o":1},{"x":40,"y":66,"w":14,"h":14,"r":"50%","bg":"#9a9aa0","border":"none","o":1},{"x":76,"y":50,"w":60,"h":60,"r":"30%","bg":"#8fa48a","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 17: The Respiratory System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 22: The Respiratory System","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified picture. The airway and lungs are drawn as simple shapes, and one breath is followed rather than the mix of air in the lungs."},"ap-18":{"id":"ap-18","after":1,"title":"From blood to urine","token":"#d8b86a","hideCore":true,"stops":[{"short":"Renal artery","place":"Renal artery","view":"torso","organs":["vessels","kidneys"],"label":[276,352,"start"],"title":"A quarter of the heart’s output goes to the kidneys.","body":"The renal arteries carry about 1,200 mL of blood to the kidneys every minute. Afferent arterioles bring it to each glomerulus.","lensCaption":"Blood carrying wastes and water","scene":"blood","path":[[262,300],[258,352],[206,352]],"lens":[{"x":20,"y":44,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":44,"y":58,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":70,"y":44,"w":30,"h":18.6,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":30,"y":72,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":60,"y":30,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":84,"y":62,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":50,"y":32,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":16,"y":66,"w":10,"h":10,"r":"50%","bg":"#d8c35a","border":"2px solid #fff","o":1}]},{"short":"Filtration","place":"Glomerulus","view":"torso","organs":["kidneys"],"label":[170,350,"end"],"title":"Glomerular filtration pushes fluid out.","body":"In the renal corpuscle (Bowman’s capsule plus the glomerulus), blood pressure forces water and small solutes like glucose, urea and ions out of the blood. Large proteins stay in.","analogy":"Like a coffee filter: water and small bits pass, big ones stay behind.","lensCaption":"Small things pass; cells and proteins stay","scene":"none","path":[[188,350]],"lens":[{"x":50,"y":50,"w":200,"h":200,"r":"50%","bg":"transparent","border":"6px solid #b5786a","o":1},{"x":40,"y":44,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":58,"y":56,"w":26,"h":16.12,"r":"50%","bg":"#c8524a","border":"3px solid #e88a80","o":1},{"x":50,"y":34,"w":18,"h":18,"r":"30%","bg":"#71836d","border":"none","o":1},{"x":20,"y":80,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":32,"y":86,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":70,"y":84,"w":10,"h":10,"r":"50%","bg":"#d8c35a","border":"2px solid #fff","o":1},{"x":84,"y":72,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1}]},{"short":"Reabsorption","place":"Renal tubule","view":"torso","organs":["kidneys"],"label":[170,360,"end"],"title":"Tubular reabsorption takes back what’s useful.","body":"Mostly in the proximal convoluted tubule, glucose, amino acids and ions are pumped back into the blood. About 95% of the water follows, controlled by ADH and aldosterone.","lensCaption":"Water and glucose returning to the blood","scene":"vessel","path":[[184,356]],"lens":[{"x":20,"y":20,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":40,"y":14,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":60,"y":18,"w":10,"h":10,"r":"50%","bg":"#d8c35a","border":"2px solid #fff","o":1},{"x":80,"y":22,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1},{"x":30,"y":56,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":56,"y":50,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":74,"y":58,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":46,"y":84,"w":12,"h":12,"r":"50%","bg":"#9fc0cf","border":"none","o":1}]},{"short":"Secretion","place":"Renal tubule","view":"torso","organs":["kidneys"],"label":[170,368,"end"],"title":"Tubular secretion adds a few more.","body":"Some substances move from the blood into the tubule, such as hydrogen ions (to adjust pH), potassium, creatinine and drugs like penicillin. What’s left is urine.","lensCaption":"Extra wastes added to the urine","scene":"vessel","path":[[186,362]],"lens":[{"x":24,"y":50,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":44,"y":56,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":64,"y":48,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":36,"y":18,"w":10,"h":10,"r":"50%","bg":"#c86d56","border":"none","o":1},{"x":62,"y":22,"w":10,"h":10,"r":"50%","bg":"#c86d56","border":"none","o":1},{"x":80,"y":52,"w":10,"h":10,"r":"50%","bg":"#c86d56","border":"none","o":1}]},{"short":"Ureter","place":"Ureter","view":"torso","organs":["ureters"],"label":[226,440,"start"],"title":"Urine drains down the ureters.","body":"Collecting ducts empty into the renal pelvis. Each 25 to 30 cm ureter carries urine to the bladder, mainly by peristalsis.","lensCaption":"Muscle waves moving urine along","scene":"muscle","path":[[190,372],[206,420],[226,470],[242,504]],"lens":[{"x":30,"y":50,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":46,"y":46,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":62,"y":54,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1}]},{"short":"Bladder","place":"Urinary bladder","view":"pelvis","organs":["bladder"],"label":[272,516,"start"],"title":"The bladder stores it.","body":"The bladder sits behind the pubic symphysis. Its wall is three layers of smooth muscle, the detrusor. Average capacity is about 500 mL; at 200 to 400 mL, stretch receptors signal the spinal cord.","lensCaption":"The bladder filling","scene":"none","path":[[250,516]],"lens":[{"x":50,"y":54,"w":180,"h":150,"r":"50% 50% 46% 46%","bg":"#f3e3b4","border":"8px solid #d8b86a","o":1},{"x":36,"y":60,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":56,"y":66,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":66,"y":50,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":44,"y":44,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1}]},{"short":"Urethra","place":"Urethra","view":"pelvis","organs":["urethra"],"label":[262,560,"start"],"title":"Micturition empties the bladder.","body":"The detrusor contracts and the external sphincter relaxes. Urine leaves through the urethra: about 3.8 cm long in females and 20 cm in males.","lensCaption":"Urine leaving the body","scene":"none","path":[[250,540],[250,568]],"lens":[{"x":50,"y":50,"w":40,"h":200,"r":"20px","bg":"#f3e3b4","border":"none","o":1},{"x":50,"y":30,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":50,"y":52,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1},{"x":50,"y":74,"w":10,"h":10,"r":"50%","bg":"#d8b86a","border":"none","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 18: The Urinary System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapter 25: The Urinary System","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified picture. One nephron stands in for the millions in each kidney, and the lens views are cartoons rather than real structures."},"ap-19":{"id":"ap-19","after":6,"title":"From sperm and egg to birth","token":"#d98aa8","hideCore":true,"dim":0.15,"stops":[{"short":"Testes","place":"Testes","view":"pelvis","organs":["testes"],"label":[268,598,"start"],"title":"Sperm are made in the testes.","body":"Seminiferous tubules make sperm by meiosis (spermatogenesis), about 300 million a day. Sertoli cells nourish them; interstitial cells of Leydig make testosterone.","lensCaption":"Sperm forming in a seminiferous tubule","scene":"follicle","path":[[258,590]],"lens":[{"x":30,"y":40,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":50,"y":30,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":70,"y":40,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":40,"y":62,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":60,"y":66,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":50,"y":50,"w":26,"h":26,"r":"50%","bg":"#f4e6c8","border":"none","o":1}]},{"short":"Duct path","place":"Epididymis and vas deferens","view":"pelvis","organs":["testes"],"label":[272,540,"start"],"title":"They mature and travel up the ducts.","body":"Sperm mature for about 20 days in the epididymis, then travel up the ductus (vas) deferens, inside the spermatic cord, to the ejaculatory duct.","lensCaption":"Sperm swimming through the duct","scene":"vessel","path":[[262,580],[270,540],[262,508],[250,516]],"lens":[{"x":20,"y":46,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":40,"y":54,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":60,"y":44,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":80,"y":52,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1}]},{"short":"Semen","place":"Prostate and glands","view":"pelvis","organs":["prostate","urethra"],"label":[264,540,"start"],"title":"Glands add the fluid of semen.","body":"Seminal vesicles add about 60% of the volume, rich in fructose. The prostate adds an alkaline fluid, and the bulbourethral glands add mucus. Semen’s pH of 7.2 to 7.6 protects sperm.","lensCaption":"Sperm in fructose-rich fluid","scene":"none","path":[[250,540]],"lens":[{"x":30,"y":40,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":60,"y":34,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":44,"y":66,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":70,"y":62,"w":12,"h":12,"r":"30%","bg":"#d8c35a","border":"none","o":1},{"x":20,"y":64,"w":12,"h":12,"r":"30%","bg":"#d8c35a","border":"none","o":1},{"x":52,"y":20,"w":12,"h":12,"r":"30%","bg":"#d8c35a","border":"none","o":1}]},{"short":"Ovulation","place":"Ovary","view":"pelvis","organs":["ovaries"],"label":[300,520,"start"],"title":"An ovary releases an egg.","body":"FSH from the anterior pituitary starts follicles growing. One becomes a graafian follicle and ruptures on about day 14 of a 28-day cycle: ovulation. The follicle then becomes the corpus luteum.","lensCaption":"An egg leaving the graafian follicle","scene":"follicle","path":[[286,508]],"lens":[{"x":50,"y":50,"w":70,"h":70,"r":"50%","bg":"#f6e3a6","border":"6px solid #f3f0e6","o":1}]},{"short":"Fertilization","place":"Fallopian tube","view":"pelvis","organs":["ovaries","uterus"],"label":[302,496,"start"],"title":"Fertilization happens in the uterine tube.","body":"Fimbriae sweep the egg into the fallopian tube. Of the sperm that reach it, only one penetrates the egg, forming a zygote. This usually happens in the upper part of the tube.","lensCaption":"One sperm entering the egg","scene":"none","path":[[276,502],[264,500]],"lens":[{"x":50,"y":50,"w":90,"h":90,"r":"50%","bg":"#f6e3a6","border":"6px solid #f3f0e6","o":1},{"x":76,"y":26,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":80,"y":50,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":72,"y":74,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":24,"y":30,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1},{"x":56,"y":40,"w":10,"h":10,"r":"50%","bg":"#b07aa0","border":"none","o":1}]},{"short":"Implantation","place":"Uterus","view":"pelvis","organs":["uterus"],"label":[274,512,"start"],"title":"The embryo implants in the endometrium.","body":"Dividing by mitosis, the zygote becomes a blastocyst. By about day 7 after ovulation it embeds in the endometrium, and the placenta begins to form.","lensCaption":"A blastocyst settling into the lining","scene":"none","path":[[254,504]],"lens":[{"x":50,"y":80,"w":200,"h":60,"r":"30px 30px 0 0","bg":"#e9a9bc","border":"none","o":1},{"x":50,"y":52,"w":60,"h":60,"r":"50%","bg":"#f6e3a6","border":"4px solid #f3d6a0","o":1},{"x":50,"y":52,"w":24,"h":24,"r":"50%","bg":"#e8c77a","border":"none","o":1}]},{"short":"Birth","place":"Uterus","view":"pelvis","organs":["uterus"],"label":[274,520,"start"],"title":"Birth is called parturition.","body":"By week 9 the embryo is a fetus. At birth, oxytocin and prostaglandins drive uterine contractions through three stages of labour: dilation, expulsion and placental.","lensCaption":"Strong contractions of the myometrium","scene":"muscle","path":[[250,520],[250,550]],"lens":[{"x":50,"y":50,"w":150,"h":150,"r":"50% 50% 44% 44%","bg":"#f2c9d5","border":"10px solid #d98aa8","o":1}]}],"sources":[{"label":"Your textbook: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 19: The Reproductive System"},{"label":"OpenStax Anatomy and Physiology 2e, Chapters 27 and 28: The Reproductive System; Development and Inheritance","url":"https://openstax.org/details/books/anatomy-and-physiology-2e"}],"scope":"A simplified picture that shows male and female organs on one body map. Sizes and positions are drawn to show the route, not true anatomy."}};